package com.sky.controller.admin;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.util.Collections;
import java.util.Set;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;

import com.sky.service.DishService;

@ExtendWith(MockitoExtension.class)
class DishControllerTest {

    @InjectMocks
    private DishController dishController;

    @Mock
    private DishService dishService;

    @Mock
    private RedisTemplate<String, Object> redisTemplate;

    private MockMvc mockMvc;

    @Test
    @DisplayName("修复后：status路径变量正确绑定 - 启用菜品")
    void testStartOrStopPathVariableBinding_Success() {
        Integer status = 1;
        Long id = 1L;
        Set<String> cacheKeys = Collections.singleton("dish_1");
        when(redisTemplate.keys("dish_*")).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);
        mockMvc = MockMvcBuilders.standaloneSetup(dishController).build();
        assertDoesNotThrow(() -> {
            mockMvc.perform(post("/admin/dish/status/{status}", status)
                    .param("id", id.toString()))
                    .andExpect(status().isOk())
                    .andExpect(jsonPath("$.code").value(1));
        });
        verify(dishService).startOrStop(status, id);
    }

    @Test
    @DisplayName("修复后：status路径变量正确绑定 - 停用菜品")
    void testStartOrStopPathVariableBinding_StatusZero() {
        Integer status = 0;
        Long id = 2L;
        Set<String> cacheKeys = Collections.singleton("dish_2");
        when(redisTemplate.keys("dish_*")).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);
        mockMvc = MockMvcBuilders.standaloneSetup(dishController).build();
        assertDoesNotThrow(() -> {
            mockMvc.perform(post("/admin/dish/status/{status}", status)
                    .param("id", id.toString()))
                    .andExpect(status().isOk());
        });
        verify(dishService).startOrStop(status, id);
    }

    @Test
    @DisplayName("边界测试：验证修复前异常的输入现在不再抛出异常")
    void testStartOrStopBoundaryCase_NoMissingPathVariable() {
        Integer status = 1;
        Long id = 3L;
        Set<String> cacheKeys = Collections.singleton("dish_3");
        when(redisTemplate.keys("dish_*")).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);
        mockMvc = MockMvcBuilders.standaloneSetup(dishController).build();
        assertDoesNotThrow(() -> {
            mockMvc.perform(post("/admin/dish/status/{status}", status)
                    .param("id", id.toString()))
                    .andExpect(status().isOk());
        });
    }

    @Test
    @DisplayName("验证id参数为null时的处理")
    void testStartOrStopWithNullId() {
        Integer status = 1;
        Set<String> cacheKeys = Collections.singleton("dish_null");
        when(redisTemplate.keys("dish_*")).thenReturn(cacheKeys);
